    static final class Windowed extends SQLiteDatabase{
        long largestBlob;Windowed(Path path)throws Exception{super(DriverManager.getConnection("jdbc:sqlite:"+path));}
        @Override public Cursor rawQuery(String sql,String[]args){Cursor c=super.rawQuery(sql,args);while(c.moveToNext())for(int i=0;i<c.getColumnCount();i++)if(c.getType(i)==Cursor.FIELD_TYPE_BLOB){long size=c.getBlob(i).length;largestBlob=Math.max(largestBlob,size);if(size>131072)throw new AssertionError("PIN_READ_EXCEEDS_128K_CURSOR_CELL:"+size);}c.moveToPosition(-1);return c;}
    }
    static long n(SQLiteDatabase db,String sql){try(Cursor c=db.rawQuery(sql,null)){return c.moveToFirst()?c.getLong(0):0;}}
    static String text(SQLiteDatabase db,String sql){try(Cursor c=db.rawQuery(sql,null)){return c.moveToFirst()?c.getString(0):null;}}
    interface Work{void run()throws Exception;}
