    static void cursor(ResearchWriteQueueR27.Batch b,EvolutionLoopR27 loop,String snap,String hash){b.add("INSERT OR REPLACE INTO r27_evolution_cursor VALUES('MAIN',?,?,?,?,?,1)",loop.generation,loop.step,hash,loop.rng.state,snap);}
    static void insertRows(SQLiteDatabase db,ReplayDatasetR27 data,int from)throws Exception{tx(db,()->{for(int t=from;t<data.size();t++){Object[]args=new Object[12];args[0]=data.issues[t];args[1]=data.ordinals[t];for(int p=0;p<10;p++)args[p+2]=data.draws[t][p];db.execSQL("INSERT INTO draws VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",args);}});}
    static ReplayDatasetR27 hot(SQLiteDatabase db){List<ReplayDatasetR27.Row> rows=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT issue,ordinal,n1,n2,n3,n4,n5,n6,n7,n8,n9,n10 FROM draws ORDER BY ordinal",null)){while(c.moveToNext()){int[]ns=new int[10];for(int p=0;p<10;p++)ns[p]=c.getInt(p+2);rows.add(new ReplayDatasetR27.Row(c.getString(0),c.getLong(1),ns));}}return ReplayDatasetR27.of(rows);}
    static void removeGuards(SQLiteDatabase db,String table){List<String>names=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT name FROM sqlite_master WHERE type='trigger' AND tbl_name=?",new String[]{table})){while(c.moveToNext())names.add(c.getString(0));}for(String name:names)db.execSQL("DROP TRIGGER \""+name.replace("\"","\"\"")+"\"");}
    static boolean rejected(Work work)throws Exception{try{work.run();return false;}catch(RuntimeException expected){if(!String.valueOf(expected.getMessage()).startsWith("R29_DATASET_PIN_"))throw expected;return true;}}
    static void fails(String id,Work work)throws Exception{boolean fail=false;try{work.run();}catch(RuntimeException expected){fail=true;}check(id,fail);}
